      "verdict": "VERIFIED",
      "verification_notes": "Evidence ev_01 directly confirms publication in Frontiers in Psychology, Volume 17, on 25 May 2026, DOI 10.3389/fpsyg.2026.1794353, and authors Xiaojun Ling, Mengqi Li, and Jiahui Sun."
    },
    {
      "fact_id": "F02",
      "verdict": "VERIFIED",
      "verification_notes": "ev_02 supports the study aims and longitudinal design; ev_04 adds the three-wave 4-month interval, consistent with the claim."
    },
    {
      "fact_id": "F03",
      "verdict": "VERIFIED",
      "verification_notes": "ev_03 provides exact sample sizes, percentages, mean age, attrition number and percentage, and states no significant differences between retained and dropped participants."
    },
    {
      "fact_id": "F04",
      "verdict": "VERIFIED",
      "verification_notes": "ev_04 confirms data collected from mothers at three time points (T1 n=619, T2 n=588, T3 n=532) spaced 4 months apart, with all questionnaires completed by mothers."
    },
    {
      "fact_id": "F05",
      "verdict": "VERIFIED",
      "verification_notes": "ev_05 matches CPRS subscales, item counts, rating scale, and Cronbach's alpha values for Closeness and Conflict."
    },
    {
      "fact_id": "F06",
      "verdict": "VERIFIED",
      "verification_notes": "ev_06 confirms the two-item caregiver screen time measure and the weighted formula (weekday x 5 + weekend x 2)/7."
    },
    {
      "fact_id": "F07",
      "verdict": "VERIFIED",
      "verification_notes": "ev_07 confirms SDQ subscales for externalizing and internalizing problems and the reported Cronbach's alpha values."
    },
    {
      "fact_id": "F08",
      "verdict": "VERIFIED",
      "verification_notes": "ev_08 lists the same correlation coefficients and p-values for screen time with parent-child relationship and problem subscales."
    },
    {
      "fact_id": "F09",
      "verdict": "VERIFIED",
      "verification_notes": "ev_09 exactly supports the standardized beta, p-value, and confidence interval for conflictual relationship predicting screen time."
    },
    {
      "fact_id": "F10",
      "verdict": "VERIFIED",
      "verification_notes": "ev_10 exactly supports the non-significant beta, p-value, and confidence interval for close relationship predicting screen time."
    },
    {
      "fact_id": "F11",
      "verdict": "VERIFIED",
      "verification_notes": "ev_11 supports the beta coefficients and confidence intervals for screen time predicting T3 internalizing and externalizing problems, with the noted ambiguity about p-values resolved by using Table 3 values as the claim does."
    },
    {
      "fact_id": "F12",
      "verdict": "VERIFIED",
      "verification_notes": "ev_12 supports the direct effects of conflictual relationship on internalizing and externalizing, with the claim accurately noting the discrepancy and using Table 3 values."
    },
    {
      "fact_id": "F13",
      "verdict": "VERIFIED",
      "verification_notes": "ev_13 supports the negative direct effects of close relationship on internalizing and externalizing with the same betas, p-values, and confidence intervals."
    },
    {
      "fact_id": "F14",
      "verdict": "VERIFIED",
      "verification_notes": "ev_14 reports the indirect beta values, p-values, and confidence intervals as claimed, including the ambiguity that CIs include zero; the claim faithfully represents the evidence."
    },
    {
      "fact_id": "F15",
      "verdict": "VERIFIED",
      "verification_notes": "ev_15 confirms all fit indices and the chi-square difference test for the partial mediation model."
    },
    {
      "fact_id": "F16",
      "verdict": "VERIFIED",
      "verification_notes": "ev_16 supports the ANOVA F-values and the pattern of SES differences for internalizing and externalizing problems."
    },
    {
      "fact_id": "F17",
      "verdict": "VERIFIED",
      "verification_notes": "ev_17 supports the limitation about no baseline levels and the caution regarding causal interpretation."
    },
    {
      "fact_id": "F18",
      "verdict": "VERIFIED",
      "verification_notes": "ev_18 supports all listed limitations: short-term design, single-informant reports, screen time duration only, and unmodeled nested data."
    },
    {
      "fact_id": "F19",
      "verdict": "VERIFIED",
      "verification_notes": "ev_19 supports the conclusion that conflictual relationship predicts behavioral problems partially through screen time and closeness directly predicts fewer externalizing behaviors without association with screen time."
    }
  ]
